01a19271-fac8-7023-ae34-035b4dc12368.raw_args:
{"command":"$f = Get-Content "$env:LOCALAPPDATA\ArtCraft Launcher\feed.json" -Raw | ConvertFrom-Json
$f.release_info.apps.PSObject.Properties | ForEach-Object { $a=$_.Value; "{0,-22} id={1,-20} repo={2,-35} latest={3}" -f $a.name,$_.Name,$a.repo,$a.latest_release.version }
echo ""
echo "app_renames:"; $f.app_renames | ConvertTo-Json -Compress
echo "repo_renames:"; $f.repo_renames | ConvertTo-Json -Compress
echo ""
echo "== Sizes =="
foreach($p in @("$env:LOCALAPPDATA\Programs\ArtCraft Launcher","C:\Program Files\CADCraft","C:\Program Files\FigCraft","$env:LOCALAPPDATA\ArtCraft Launcher","$env:APPDATA\ai.storyteller.artcraft-launcher","$env:APPDATA\ai.storyteller.cadcraft","$env:APPDATA\CADCraft","$env:APPDATA\FigCraft")){
  if(Test-Path $p){ $s=(Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum); "{0}  files={1}  MB={2:N1}" -f $p,$s.Count,($s.Sum/1MB) }
}
echo ""
echo "== Only craft dirs in Program Files / Local Programs =="
Get-ChildItem 'C:\Program Files',"$env:LOCALAPPDATA\Programs" -Directory -ErrorAction SilentlyContinue | Where-Object Name -match 'craft' | Select-Object FullName
echo "== Uninstall entries (all craft) =="
Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object DisplayName -match 'craft' | Select-Object DisplayName,DisplayVersion,Publisher | Format-Table -AutoSize | Out-String","description":"List catalog apps and sizes concisely"}

